  async treeBenchmark(
    opts: { frames?: number; step?: number; withoutTrees?: boolean; download?: boolean; gpuTimer?: boolean } = {},
  ): Promise<TreeBenchReport> {
    const frames = opts.frames ?? 1200;
    const step = opts.step ?? 0.5;
    const wasRunning = this.running;
    this.stop();
    const gl = this.renderer.getContext();
    const path = benchPath(this.world, frames, step);
    const yieldFrame = () => new Promise<void>((r) => setTimeout(r, 0));
    const runs: BenchRun[] = [];
    for (const trees of opts.withoutTrees === false ? [true] : [true, false]) {
      this.trees.group.visible = trees;
      // Warm-up: stream terrain, scatter and tree batches along the path.
      for (let i = 0; i < frames; i += 8) {
        this.benchFrame(path.poses[i], trees, 40);
        if (i % 64 === 0) await yieldFrame();
      }
      gl.finish();
      // Frame times with the GPU timer off: its queries stall the pipeline now and then (they would show as spikes).
      this.trees.measure = false;
      const times: number[] = [];
      const select: number[] = [];
      let active = 0;
      const detail: { ms: number; selectMs: number; jobMs: number; commit: boolean }[] = [];
      for (let i = 0; i < frames; i++) {
        const t0 = performance.now();
        const commits = this.trees.commits;
        this.benchFrame(path.poses[i], trees, 2.5);
        gl.finish();
        times.push(performance.now() - t0);
        if (trees) {
          select.push(this.trees.current.selectMs);
          active += this.trees.current.active;
          detail.push({
            ms: times[times.length - 1],
            selectMs: this.trees.current.selectMs,
            jobMs: this.trees.current.jobMs,
            commit: this.trees.commits !== commits,
          });
        }
        if (i % 60 === 59) await yieldFrame();
      }
      // Tree GPU time: a second pass over every 4th pose with the timer on.
      let gpu: number[] = [];
      if (trees && this.trees.timer?.available && opts.gpuTimer !== false) {
        this.trees.measure = true;
        this.trees.update(this.camera);
        this.trees.timer.takeSamples();
        for (let i = 0; i < frames; i += 4) {
          this.benchFrame(path.poses[i], trees, 2.5);
          gl.finish();
          if (i % 120 === 0) await yieldFrame();
        }
        this.trees.update(this.camera);
        gpu = this.trees.timer.takeSamples();
        this.trees.measure = false;
      }
      const run = summarize(trees, times, gpu, select);
      if (trees) {
        run.worstFrames = detail.sort((a, b) => b.ms - a.ms).slice(0, 8);
        run.active = Math.round(active / frames);
      }
      runs.push(run);
    }
    this.trees.group.visible = true;
    this.trees.measure = false;
    const size = this.renderer.getDrawingBufferSize(new Vector2());
    const report: TreeBenchReport = {
      stage: this.world.map.id,
      quality: this.opts.quality.name,
      resolution: `${size.x}x${size.y}`,
      pixelRatio: this.renderer.getPixelRatio(),
      gpu: gpuName(this.renderer),
      date: new Date().toISOString(),
      path: { start: path.start, metres: frames * step, step },
      loadMs: Math.round(this.loadMs),
      treeLoad: { ...this.treeLibrary.stats },
      runs,
      treeCostMs: runs.length > 1 ? Math.round((runs[0].avgMs - runs[1].avgMs) * 100) / 100 : null,
      result: checkBudget(runs, this.treeLibrary.stats.totalMs),
    };
    console.table(runs);
    console.log('tree benchmark', report);
    if (opts.download !== false) writeReport(report);
    this.placeAtSpawn();
    if (wasRunning) this.start();
    return report;
  }

  /** One benchmark frame: camera on the path, world streaming, render (no car / physics / effects). */
  private benchFrame(pose: { pos: Vector3; look: Vector3 }, trees: boolean, terrainBudget: number): void {
    const cam = this.camera;
    cam.position.copy(pose.pos);
    cam.up.set(0, 1, 0);
    cam.lookAt(pose.look);
    cam.fov = 65;
    cam.updateProjectionMatrix();
    this.terrain.update(cam.position, terrainBudget);
    this.roadCull.update(cam.position);
    this.streamer.update(cam.position);
    if (trees) this.trees.update(cam);
    const dir = cam.getWorldDirection(this.camDir);
    const halfFov = Math.atan(Math.tan((cam.fov * Math.PI) / 360) * cam.aspect);
    this.streamer.setView({ yaw: Math.atan2(dir.z, dir.x), half: halfFov + VIEW_MARGIN });
    this.env.update(cam.position, dir);
    this.env.follow(cam.position);
    this.canopy.update();
    this.renderer.render(this.scene, cam);
  }

  private frame(dt: number): void {
import type { BufferGeometry, Mesh, WebGLRenderer } from 'three';

/**
 * Tree cost counters (spec: trees/Performance.md#counters): what the tree passes drew last frame, the GPU time of
 * the tree main pass and the tree shadow pass on their own, the CPU time of level selection, and what loading the
 * variants cost. Filled by trees/draw.ts and trees/load.ts, shown by trees/overlay.ts and the benchmark.
 */

export interface TreeFrameStats {
  /** Trees drawn settled at LOD0, LOD1, the impostor and trees in a fade (main pass). */
  levels: [number, number, number];
  fading: number;
  /** Foliage sprites drawn (main pass; before the shader's thinning). */
  sprites: number;
  /** Trees re-selected this frame (the rest sit settled in static batches until the next job). */
  active: number;
  /** Draw calls and triangles submitted by the tree meshes: main pass and shadow pass. */
  mainDraws: number;
  mainTriangles: number;
  shadowDraws: number;
  shadowTriangles: number;
  /** CPU ms: per-frame level selection + fade updates (active trees), and the time-sliced batching job. */
  selectMs: number;
  jobMs: number;
  /** GPU ms of the tree draws, main and shadow pass (smoothed over the last frames whose timings came back); NaN = no timer. */
  gpuMainMs: number;
  gpuShadowMs: number;
}

export function emptyFrameStats(): TreeFrameStats {
  return {
    levels: [0, 0, 0],
    fading: 0,
    sprites: 0,
    active: 0,
    mainDraws: 0,
    mainTriangles: 0,
    shadowDraws: 0,
    shadowTriangles: 0,
    selectMs: 0,
    jobMs: 0,
    gpuMainMs: NaN,
    gpuShadowMs: NaN,
  };
}

export interface TreeLoadStats {
  variants: number;
  /** Variants read from the disk cache (the rest were generated). */
  cached: number;
  /** ms spent deriving + meshing (summed over the worker's variants) and baking impostors. */
  generateMs: number;
  bakeMs: number;
  /** Wall time of the whole tree load (ms). */
  totalMs: number;
  /** Bytes of the variants on the GPU (geometry + impostor atlases with mips + leaf / bark textures) and on disk. */
  gpuBytes: number;
  diskBytes: number;
}

