// Local verification helper (not committed). Steps: wait:ms, shot, save:<file>=<js>, or js.
import { spawn } from 'node:child_process';
import { writeFileSync, readdirSync } from 'node:fs';
import { homedir } from 'node:os';
const [url, out, ...steps] = process.argv.slice(2);
const base = `${homedir()}/.cache/ms-playwright/chromium_headless_shell-1243/`;
const bin = base + readdirSync(base).find((d) => d.startsWith('chrome')) + '/chrome-headless-shell';
const port = 9300 + Math.floor(Math.random() * 500);
const proc = spawn(bin, ['--no-sandbox', '--use-angle=gl-egl', '--enable-gpu', '--ignore-gpu-blocklist', `--remote-debugging-port=${port}`, 'about:blank'], { stdio: 'ignore' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let targets = [];
for (let i = 0; i < 50 && !targets.length; i++) {
  try { targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); } catch { /* not up yet */ }
  await sleep(200);
}
const ws = new WebSocket(targets.find((t) => t.type === 'page').webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));
let id = 0;
const pending = new Map();
const logs = [];
ws.onmessage = (e) => {
  const m = JSON.parse(e.data);
  if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); }
  else if (m.method === 'Runtime.exceptionThrown') logs.push(`[exception] ${JSON.stringify(m.params.exceptionDetails).slice(0, 1500)}`);
  else if (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error') logs.push(`[error] ${m.params.args.map((a) => a.value ?? a.description).join(' ').slice(0, 2000)}`);
};
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
await send('Runtime.enable');
await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride', { width: Number(process.env.W ?? 2117), height: Number(process.env.H ?? 1018), deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url });
let n = 0;
for (const step of steps) {
  if (step.startsWith('wait:')) { await sleep(Number(step.slice(5))); continue; }
  if (step.startsWith('nav:')) { await send('Page.navigate', { url: step.slice(4) }); await sleep(1000); continue; }
  if (step === 'shot') { const r = await send('Page.captureScreenshot', { format: 'png' }); writeFileSync(`${out}-${n++}.png`, Buffer.from(r.result.data, 'base64')); continue; }
  let file = null; let expr = step;
  if (step.startsWith('save:')) { const i = step.indexOf('='); file = step.slice(5, i); expr = step.slice(i + 1); }
  const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true, timeout: 1800000 });
  const v = r.result?.result?.value ?? r.result?.exceptionDetails?.exception?.description;
  if (file) writeFileSync(file, JSON.stringify(v, null, 1));
  logs.push(`< ${JSON.stringify(v).slice(0, 600)}`);
}
writeFileSync(`${out}.log`, logs.join('\n'));
ws.close();
proc.kill('SIGKILL');
process.exit(0);
EOF
