WAIT="(async () => { for (let i = 0; i < 600; i++) { if (window.__rally && __rally.loadMs > 0) return __rally.loadMs; await new Promise(r => setTimeout(r, 500)); } return 'timeout'; })()"
if [ -n "$CMP" ]; then C="compare: $(cat $CMP),"; else C=""; fi
echo "$C" > /tmp/cmp.js
BENCH="(async () => { const r = await __rally.treeBenchmark({ download: false, machine: 'Radeon 890M laptop', $(cat /tmp/cmp.js) }); return r; })()"
timeout 1700 node .shots/cdp.mjs "$U" .shots/$NAME "$WAIT" "nav:$U" "$WAIT" "wait:3000" "save:.shots/$NAME.json=$BENCH"
