print('fail:', r['result']['failures'])
for s in sorted(t.get('spikes',[]), key=lambda s:-s['ms'])[:6]: print('  spike', s)
if r.get('comparison'):
  c=r['comparison']; keys=['treeCostMs','trees.avgMs','trees.low1Ms','trees.worstMs','trees.treeMainGpuMs','trees.treeShadowGpuMs','trees.selectMs','trees.active','trees.spikeFrames']
  print('vs before:', {k:c.get(k) for k in keys})
PY
EOF
