import { spawn } from 'node:child_process';
import { writeFileSync, readdirSync } from 'node:fs';
import { homedir } from 'node:os';
const url = process.argv[2];
const base = `${homedir()}/.cache/ms-playwright/chromium_headless_shell-1243/`;
const bin = base + readdirSync(base).find((d) => d.startsWith('chrome')) + '/chrome-headless-shell';
const port = 9300 + Math.floor(Math.random() * 500);
const proc = spawn(bin, ['--no-sandbox', '--use-angle=gl-egl', '--enable-gpu', '--ignore-gpu-blocklist', `--remote-debugging-port=${port}`, 'about:blank'], { stdio: 'ignore' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let targets = [];
for (let i = 0; i < 50 && !targets.length; i++) { try { targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); } catch {} await sleep(200); }
const ver = await (await fetch(`http://127.0.0.1:${port}/json/version`)).json();
const bws = new WebSocket(ver.webSocketDebuggerUrl);
await new Promise((r) => (bws.onopen = r));
const ws = new WebSocket(targets.find((t) => t.type === 'page').webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));
const mk = (sock) => { let id = 0; const pending = new Map(); const handlers = []; sock.onmessage = (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } else handlers.forEach((h) => h(m)); }; return { send: (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); sock.send(JSON.stringify({ id: i, method, params })); }), on: (h) => handlers.push(h) }; };
const page = mk(ws); const browser = mk(bws);
const ev = async (e) => (await page.send('Runtime.evaluate', { expression: e, awaitPromise: true, returnByValue: true, timeout: 1800000 })).result?.result?.value;
await page.send('Runtime.enable');
await page.send('Emulation.setDeviceMetricsOverride', { width: 2117, height: 1018, deviceScaleFactor: 1, mobile: false });
await page.send('Page.navigate', { url });
await ev("(async () => { for (let i = 0; i < 600; i++) { if (window.__rally && __rally.loadMs > 0) return 1; await new Promise(r => setTimeout(r, 500)); } return 0; })()");
await sleep(2000);
const events = [];
browser.on((m) => { if (m.method === 'Tracing.dataCollected') events.push(...m.params.value); });
const done = new Promise((r) => browser.on((m) => { if (m.method === 'Tracing.tracingComplete') r(); }));
await browser.send('Tracing.start', { traceConfig: { includedCategories: ['gpu', 'gpu.service', 'disabled-by-default-gpu.service', 'toplevel', 'gpu.angle', 'disabled-by-default-gpu.decoder', 'v8', 'blink', 'disabled-by-default-devtools.timeline'] } });
const r = await ev("(async () => { const g=__rally; const rep = await g.treeBenchmark({download:false,withoutTrees:false,gpuTimer:false,frames:400}); return rep.runs[0].spikes.map(s=>[s.frame,s.ms]); })()");
await browser.send('Tracing.end');
await done;
const procs = {}; for (const e of events) if (e.name === 'process_name') procs[e.pid] = e.args.name;
const thr = {}; for (const e of events) if (e.name === 'thread_name') thr[e.pid + ':' + e.tid] = e.args.name;
const long = events.filter((e) => e.ph === 'X' && e.dur > 100000).map((e) => `${(e.dur / 1000).toFixed(0)}ms ${procs[e.pid]}/${thr[e.pid + ':' + e.tid]} ${e.cat} ${e.name} ${JSON.stringify(e.args).slice(0, 150)}`);
writeFileSync('.shots/trace.txt', JSON.stringify(r) + '\n' + long.join('\n'));
proc.kill('SIGKILL'); process.exit(0);
EOF
timeout 1500 node .shots/trace.mjs "http://localhost:3123/games/rally/?map=jackie&mute=1&quality=medium"; sort -rn .shots/trace.txt | head -40 | cut -c1-260

